patches.diff_content:
--- a/src/main/java/com/app/auth/AuthManager.java
+++ b/src/main/java/com/app/auth/AuthManager.java
@@ -1,4 +1,12 @@
     public void onOtpReceived(String code) {
-        otpTextView.setText(code);
-        verifyButton.setEnabled(true);
+        if (code == null || code.trim().isEmpty()) {
+            Log.w("AuthManager", "Received empty or null OTP code. Ignoring.");
+            return;
+        }
+        if (otpTextView != null) {
+            otpTextView.setText(code);
+        }
+        if (verifyButton != null) {
+            verifyButton.setEnabled(true);
+        }
     }

